  1→use serde::{Deserialize, Serialize};
  2→use std::collections::HashMap;
  3→use std::path::{Path, PathBuf};
  4→use tracing::warn;
  5→
  6→/// Dockerfile build configuration for building images from source.
  7→/// Used when devcontainer.json specifies `build.dockerfile` or when
  8→/// configured directly in .dual.toml.
  9→#[derive(Debug, Serialize, Deserialize, PartialEq, Clone)]
 10→pub struct DockerfileBuild {
 11→    /// Path to the Dockerfile (relative to base_dir or workspace root)
 12→    pub path: String,
 13→
 14→    /// Build context directory (relative to base_dir or workspace root)
 15→    #[serde(default = "default_build_context")]
 16→    pub context: String,
 17→
 18→    /// Docker build arguments (--build-arg)
 19→    #[serde(default)]
 20→    pub args: HashMap<String, String>,
 21→
 22→    /// Target build stage for multi-stage builds
 23→    #[serde(skip_serializing_if = "Option::is_none")]
 24→    pub target: Option<String>,
 25→
 26→    /// Base directory for resolving relative paths (set by devcontainer loader).
 27→    /// When loaded from .dual.toml, this is None and paths are relative to workspace root.
 28→    #[serde(skip)]
 29→    pub base_dir: Option<PathBuf>,
 30→}
 31→
 32→fn default_build_context() -> String {
 33→    ".".to_string()
 34→}
 35→
 36→const HINTS_FILENAME: &str = ".dual.toml";
 37→const DEFAULT_IMAGE: &str = "node:20";
 38→
 39→/// Shared configuration file propagation settings.
 40→#[derive(Debug, Serialize, Deserialize, PartialEq, Clone)]
 41→pub struct SharedConfig {
 42→    /// Files and directories to share across workspaces.
 43→    /// e.g. [".vercel", ".env.local", ".env"]
 44→    #[serde(default)]
 45→    pub files: Vec<String>,
 46→}
 47→
 48→/// Dual-specific orchestration config, read from .dual.toml.
 49→///
 50→/// Container configuration (image, ports, setup, env) lives in devcontainer.json.
 51→/// This struct contains only Dual-specific fields that devcontainer can't express.
 52→#[derive(Debug, Serialize, Deserialize, PartialEq, Clone)]
 53→pub struct DualConfig {
 54→    /// Explicit path to devcontainer.json (auto-detected if omitted)
 55→    #[serde(skip_serializing_if = "Option::is_none")]
 56→    pub devcontainer: Option<String>,
 57→
 58→    /// Additional commands to route to the container (merged with defaults)
 59→    #[serde(default)]
 60→    pub extra_commands: Vec<String>,
 61→
 62→    /// Directories to isolate with anonymous Docker volumes
 63→    #[serde(default = "default_anonymous_volumes")]
 64→    pub anonymous_volumes: Vec<String>,
 65→
 66→    /// Shared files to propagate across workspaces
 67→    #[serde(skip_serializing_if = "Option::is_none")]
 68→    pub shared: Option<SharedConfig>,
 69→}
 70→
 71→impl Default for DualConfig {
 72→    fn default() -> Self {
 73→        Self {
 74→            devcontainer: None,
 75→            extra_commands: Vec::new(),
 76→            anonymous_volumes: default_anonymous_volumes(),
 77→            shared: None,
 78→        }
 79→    }
 80→}
 81→
 82→/// Per-repo runtime hints — the merged internal representation used by all consumers.
 83→///
 84→/// Built from DualConfig (.dual.toml) + DevcontainerJson (devcontainer.json).
 85→/// Consumer code (container, proxy, shell) uses this struct exclusively.
 86→#[derive(Debug, Serialize, Deserialize, PartialEq, Clone)]
 87→pub struct RepoHints {
 88→    /// Docker image to use for containers (default: "node:20")
 89→    #[serde(default = "default_image")]
 90→    pub image: String,
 91→
 92→    /// Ports that services bind to inside the container
 93→    #[serde(default)]
 94→    pub ports: Vec<u16>,
 95→
 96→    /// Setup command to run after container creation (e.g. "pnpm install")
 97→    pub setup: Option<String>,
 98→
 99→    /// Environment variables for the container
100→    #[serde(default)]
101→    pub env: HashMap<String, String>,
102→
103→    /// Additional commands to route to the container (merged with defaults)
104→    #[serde(default)]
105→    pub extra_commands: Vec<String>,
106→
107→    /// Directories to isolate with anonymous Docker volumes
108→    #[serde(default = "default_anonymous_volumes")]
109→    pub anonymous_volumes: Vec<String>,
110→
111→    /// Shared files to propagate across workspaces
112→    #[serde(skip_serializing_if = "Option::is_none")]
113→    pub shared: Option<SharedConfig>,
114→
115→    /// Dockerfile build config — if set, build image instead of pulling.
116→    /// Sourced from devcontainer.json build field.
117→    #[serde(skip_serializing_if = "Option::is_none")]
118→    pub dockerfile: Option<DockerfileBuild>,
119→}
120→
121→fn default_image() -> String {
122→    DEFAULT_IMAGE.to_string()
123→}
124→
125→fn default_anonymous_volumes() -> Vec<String> {
126→    vec!["node_modules".to_string()]
127→}
128→
129→impl Default for RepoHints {
130→    fn default() -> Self {
131→        Self {
132→            image: DEFAULT_IMAGE.to_string(),
133→            ports: Vec::new(),
134→            setup: None,
135→            env: HashMap::new(),
136→            extra_commands: Vec::new(),
137→            anonymous_volumes: default_anonymous_volumes(),
138→            shared: None,
139→            dockerfile: None,
140→        }
141→    }
142→}
