144→/// Get the shared config directory for a repo: ~/.dual/shared/{repo}/
145→pub fn shared_dir(repo: &str) -> Option<PathBuf> {
146→    dirs::home_dir().map(|home| home.join(".dual").join("shared").join(repo))
147→}
148→
149→/// Load RepoHints from a workspace directory.
150→///
151→/// Loading flow:
152→/// 1. Read `.dual.toml` → `DualConfig` (defaults if missing)
153→/// 2. Resolve devcontainer.json path (explicit from DualConfig or auto-detect)
154→/// 3. Parse devcontainer.json → `RepoHints` for container fields
155→/// 4. Merge DualConfig fields + devcontainer RepoHints → final `RepoHints`
156→pub fn load_hints(workspace_dir: &Path) -> Result<RepoHints, HintsError> {
157→    let dual_config = load_dual_config(workspace_dir)?;
158→    let dc_path = resolve_devcontainer_path(workspace_dir, &dual_config);
159→
160→    // Load container config from devcontainer.json
161→    let dc_hints = dc_path.and_then(|path| {
162→        let devcontainer_dir = path.parent().unwrap_or(workspace_dir);
163→        let contents = std::fs::read_to_string(&path).ok()?;
164→        let dc = crate::devcontainer::parse_devcontainer(&contents).ok()?;
165→        Some(crate::devcontainer::to_repo_hints(&dc, devcontainer_dir))
166→    });
167→
168→    Ok(merge_config(&dual_config, dc_hints.as_ref()))
169→}
170→
171→/// Load DualConfig from .dual.toml. Returns defaults if file doesn't exist.
172→fn load_dual_config(workspace_dir: &Path) -> Result<DualConfig, HintsError> {
173→    let path = workspace_dir.join(HINTS_FILENAME);
174→
175→    if !path.exists() {
176→        return Ok(DualConfig::default());
177→    }
178→
179→    let contents =
180→        std::fs::read_to_string(&path).map_err(|e| HintsError::ReadError(path.clone(), e))?;
181→
182→    // Check for deprecated fields and warn
183→    check_deprecated_fields(&contents, &path);
184→
185→    let config: DualConfig =
186→        toml::from_str(&contents).map_err(|e| HintsError::ParseError(path, e))?;
187→    Ok(config)
188→}
189→
190→/// Warn if .dual.toml contains deprecated container config fields.
191→fn check_deprecated_fields(contents: &str, path: &Path) {
192→    let deprecated = [
193→        ("image", "image"),
194→        ("ports", "forwardPorts"),
195→        ("setup", "postCreateCommand"),
196→        ("[env]", "containerEnv"),
197→    ];
198→
199→    for (old_field, new_field) in &deprecated {
200→        // Check for the field as a top-level key (not in a comment)
201→        for line in contents.lines() {
202→            let trimmed = line.trim();
203→            if trimmed.starts_with('#') {
204→                continue;
205→            }
206→            let matches = if *old_field == "[env]" {
207→                trimmed == "[env]"
208→            } else {
209→                trimmed.starts_with(&format!("{old_field} "))
210→                    || trimmed.starts_with(&format!("{old_field}="))
211→            };
212→            if matches {
213→                warn!(
214→                    "{}: '{}' should be moved to devcontainer.json as '{}'. \
215→                     Container config fields in .dual.toml are deprecated.",
216→                    path.display(),
217→                    old_field,
218→                    new_field
219→                );
220→                break;
221→            }
222→        }
223→    }
224→}
225→
226→/// Resolve the path to devcontainer.json.
227→///
228→/// Uses explicit path from DualConfig if set, otherwise auto-detects.
229→fn resolve_devcontainer_path(workspace_dir: &Path, config: &DualConfig) -> Option<PathBuf> {
230→    if let Some(ref explicit) = config.devcontainer {
231→        let path = workspace_dir.join(explicit);
232→        if path.exists() {
233→            return Some(path);
234→        }
235→        warn!(
236→            "devcontainer path '{}' specified in .dual.toml does not exist",
237→            path.display()
238→        );
239→        return None;
240→    }
241→
242→    crate::devcontainer::find_devcontainer_json(workspace_dir)
243→}
244→
245→/// Merge DualConfig + devcontainer RepoHints into final RepoHints.
246→///
247→/// devcontainer.json provides: image, ports, setup, env, dockerfile
248→/// DualConfig provides: extra_commands, anonymous_volumes, shared
249→fn merge_config(dual: &DualConfig, dc_hints: Option<&RepoHints>) -> RepoHints {
250→    let base = dc_hints.cloned().unwrap_or_default();
251→
252→    RepoHints {
253→        // Container fields come from devcontainer.json (or defaults)
254→        image: base.image,
255→        ports: base.ports,
256→        setup: base.setup,
257→        env: base.env,
258→        dockerfile: base.dockerfile,
259→
260→        // Dual-specific fields come from .dual.toml
261→        extra_commands: dual.extra_commands.clone(),
262→        anonymous_volumes: dual.anonymous_volumes.clone(),
263→        shared: dual.shared.clone(),
264→    }
265→}
266→
267→/// Write a default .dual.toml with Dual-specific fields only.
268→/// Container config belongs in devcontainer.json.
269→pub fn write_default_dual_config(repo_root: &Path) -> Result<(), HintsError> {
270→    let template = r#"# Dual workspace configuration
271→# See: https://github.com/jeevanpillay/dual
272→#
273→# Container config (image, ports, setup, env) goes in devcontainer.json.
274→# This file contains only Dual-specific orchestration settings.
275→
276→# Explicit path to devcontainer.json (auto-detected if omitted)
277→# devcontainer = ".devcontainer/devcontainer.json"
278→
279→# Commands to route to the container (in addition to defaults)
280→# Default: npm, npx, pnpm, node, python, python3, pip, pip3, curl, make
281→# Example: extra_commands = ["cargo", "go", "ruby"]
282→# extra_commands = []
283→
284→# Directories to isolate with anonymous Docker volumes
285→# These directories get their own volume so they don't sync between host/container
286→# Example: anonymous_volumes = ["node_modules", ".next", "target"]
287→# anonymous_volumes = ["node_modules"]
288→
289→# Files to share across all workspaces of this repo
290→# These are gitignored files that should be available in every branch workspace
291→# [shared]
292→# files = [".env.local", ".vercel"]
293→"#;
294→    let hints_path = repo_root.join(HINTS_FILENAME);
295→    std::fs::write(&hints_path, template).map_err(|e| HintsError::WriteError(hints_path, e))?;
296→    Ok(())
297→}
298→
299→/// Write a default devcontainer.json with minimal container config.
300→/// Creates .devcontainer/ directory if it doesn't exist.
301→pub fn write_default_devcontainer(repo_root: &Path) -> Result<(), HintsError> {
302→    let dc_dir = repo_root.join(".devcontainer");
303→    std::fs::create_dir_all(&dc_dir).map_err(|e| HintsError::WriteError(dc_dir.clone(), e))?;
304→
305→    let dc_path = dc_dir.join("devcontainer.json");
306→    let content = r#"{
307→    "image": "node:20"
308→}
309→"#;
310→    std::fs::write(&dc_path, content).map_err(|e| HintsError::WriteError(dc_path, e))?;
311→    Ok(())
312→}
313→
314→/// Write DualConfig to a workspace directory's .dual.toml.
315→pub fn write_dual_config(workspace_dir: &Path, config: &DualConfig) -> Result<(), HintsError> {
316→    let path = workspace_dir.join(HINTS_FILENAME);
317→    let contents = toml::to_string_pretty(config).map_err(HintsError::SerializeError)?;
318→    std::fs::write(&path, contents).map_err(|e| HintsError::WriteError(path, e))?;
319→    Ok(())
320→}
321→
322→/// Parse DualConfig from TOML string (for testing).
323→pub fn parse_dual_config(toml_str: &str) -> Result<DualConfig, HintsError> {
324→    let config: DualConfig = toml::from_str(toml_str)
325→        .map_err(|e| HintsError::ParseError(PathBuf::from("<string>"), e))?;
326→    Ok(config)
327→}
328→
329→/// Compute the workspace identifier from repo + branch.
330→/// e.g. ("lightfast", "feat/auth") → "lightfast-feat__auth"
331→pub fn workspace_id(repo: &str, branch: &str) -> String {
332→    format!("{}-{}", repo, encode_branch(branch))
333→}
334→
335→/// Get the workspace directory for a repo + branch combination.
336→/// Layout: {workspace_root}/{repo}/{encoded_branch}/
337→pub fn workspace_dir(workspace_root: &Path, repo: &str, branch: &str) -> PathBuf {
338→    workspace_root.join(repo).join(encode_branch(branch))
339→}
340→
341→/// Compute the container name for a repo + branch combination.
342→/// Pattern: dual-{repo}-{encoded_branch}
343→pub fn container_name(repo: &str, branch: &str) -> String {
344→    format!("dual-{}-{}", repo, encode_branch(branch))
345→}
346→
347→/// Compute the tmux session name for a repo + branch combination.
348→/// Uses the same naming convention as container names for consistency.
349→pub fn session_name(repo: &str, branch: &str) -> String {
350→    container_name(repo, branch)
351→}
352→
353→/// Encode a branch name for filesystem use.
354→/// Replaces `/` with `__` (double underscore).
355→/// e.g. "feat/auth" → "feat__auth"
356→pub fn encode_branch(branch: &str) -> String {
357→    branch.replace('/', "__")
358→}
359→
360→/// Decode an encoded branch name back to the original.
361→/// Replaces `__` with `/`.
362→/// e.g. "feat__auth" → "feat/auth"
363→pub fn decode_branch(encoded: &str) -> String {
364→    encoded.replace("__", "/")
365→}
366→
367→#[derive(Debug, thiserror::Error)]
368→pub enum HintsError {
369→    #[error("Failed to read {path}: {err}", path = .0.display(), err = .1)]
370→    ReadError(PathBuf, std::io::Error),
371→
372→    #[error("Failed to write {path}: {err}", path = .0.display(), err = .1)]
373→    WriteError(PathBuf, std::io::Error),
374→
375→    #[error("Failed to parse {path}: {err}", path = .0.display(), err = .1)]
376→    ParseError(PathBuf, toml::de::Error),
377→
378→    #[error("Failed to serialize hints: {0}")]
379→    SerializeError(toml::ser::Error),
380→}
