 128→/// Register the current repo as a dual workspace.
 129→fn cmd_add(name: Option<&str>) -> i32 {
 130→    // Detect git repo info from current directory
 131→    let (repo_root, url, branch) = match detect_git_repo() {
 132→        Ok(info) => info,
 133→        Err(e) => {
 134→            error!("{e}");
 135→            return 1;
 136→        }
 137→    };
 138→
 139→    // Derive repo name
 140→    let repo_name = match name {
 141→        Some(n) => n.to_string(),
 142→        None => derive_repo_name(&repo_root),
 143→    };
 144→
 145→    // Load or create state
 146→    let mut st = match state::load() {
 147→        Ok(s) => s,
 148→        Err(e) => {
 149→            error!("{e}");
 150→            return 1;
 151→        }
 152→    };
 153→
 154→    // Check for duplicates
 155→    if st.has_workspace(&repo_name, &branch) {
 156→        error!("workspace {}/{} already exists", repo_name, branch);
 157→        return 1;
 158→    }
 159→
 160→    // Create .dual.toml if missing (Dual-specific orchestration config)
 161→    let hints_path = repo_root.join(".dual.toml");
 162→    if !hints_path.exists() {
 163→        if let Err(e) = config::write_default_dual_config(&repo_root) {
 164→            warn!("failed to write .dual.toml: {e}");
 165→        } else {
 166→            info!("Created .dual.toml (Dual orchestration settings)");
 167→        }
 168→    }
 169→
 170→    // Create devcontainer.json if no devcontainer config exists (container config)
 171→    if dual::devcontainer::find_devcontainer_json(&repo_root).is_none() {
 172→        if let Err(e) = config::write_default_devcontainer(&repo_root) {
 173→            warn!("failed to write devcontainer.json: {e}");
 174→        } else {
 175→            info!("Created .devcontainer/devcontainer.json (image: node:20)");
 176→            info!("Edit it to customize image, ports, setup command, and env vars.");
 177→        }
 178→    }
 179→
 180→    // Initialize shared directory if [shared] is configured
 181→    let hints = config::load_hints(&repo_root).unwrap_or_default();
 182→    if let Some(ref shared_config) = hints.shared
 183→        && !shared_config.files.is_empty()
 184→    {
 185→        match shared::ensure_shared_dir(&repo_name) {
 186→            Ok(shared_dir) => {
 187→                match shared::init_from_main(&repo_root, &shared_dir, &shared_config.files) {
 188→                    Ok(moved) => {
 189→                        for f in &moved {
 190→                            info!("  shared: {f} → ~/.dual/shared/{repo_name}/");
 191→                        }
 192→                    }
 193→                    Err(e) => warn!("shared init failed: {e}"),
 194→                }
 195→            }
 196→            Err(e) => warn!("could not create shared directory: {e}"),
 197→        }
 198→    }
 199→
 200→    // Add workspace entry
 201→    let entry = state::WorkspaceEntry {
 202→        repo: repo_name.clone(),
 203→        url,
 204→        branch: branch.clone(),
 205→        path: Some(repo_root.to_string_lossy().to_string()),
 206→    };
 207→
 208→    if let Err(e) = st.add_workspace(entry) {
 209→        error!("{e}");
 210→        return 1;
 211→    }
 212→
 213→    // Save state
 214→    if let Err(e) = state::save(&st) {
 215→        error!("failed to save state: {e}");
 216→        return 1;
 217→    }
 218→
 219→    let ws_id = config::workspace_id(&repo_name, &branch);
 220→    info!("Added workspace: {ws_id}");
 221→    info!("Use `dual launch {ws_id}` to start.");
 222→    0
 223→}
