1009→/// Derive a short repo name from a directory path.
1010→/// "/Users/jeevan/code/lightfast" → "lightfast"
1011→fn derive_repo_name(path: &std::path::Path) -> String {
1012→    path.file_name()
1013→        .and_then(|n| n.to_str())
1014→        .unwrap_or("repo")
1015→        .to_string()
1016→}
