273→/// Get all configured URLs for workspaces.
274→pub fn workspace_urls(state: &WorkspaceState) -> Vec<(String, Vec<String>)> {
275→    let mut result = Vec::new();
276→
277→    for entry in state.all_workspaces() {
278→        let container_name = config::container_name(&entry.repo, &entry.branch);
279→        let workspace_id = config::workspace_id(&entry.repo, &entry.branch);
280→        let is_running = container::status(&container_name) == container::ContainerStatus::Running;
281→
282→        // Load hints to get ports
283→        let ws_dir = state.workspace_dir(entry);
284→        let hints = config::load_hints(&ws_dir).unwrap_or_default();
285→
286→        let mut urls = Vec::new();
287→        for &port in &hints.ports {
288→            let status = if is_running { "\u{25cf}" } else { "\u{25cb}" };
289→            urls.push(format!("  {status} {workspace_id}.localhost:{port}"));
290→        }
291→
292→        if !urls.is_empty() {
293→            result.push((workspace_id, urls));
294→        }
295→    }
296→
297→    result
298→}
