    #[test]
    fn parse_post_create_command_array() {
        let json = r#"{"postCreateCommand": ["pnpm", "install"]}"#;
        let dc = parse_devcontainer(json).unwrap();
        assert_eq!(
            dc.post_create_command.unwrap().to_shell_command(),
