    // Branch workspace: copy from shared dir
    match shared::copy_to_branch(&workspace_dir, &shared_dir, &shared_config.files) {
        Ok(copied) => {
            if copied.is_empty() {
                info!(
                    "No shared files available yet. Run `dual sync` in the main workspace first."
                );
            } else {
                for f in &copied {
                    info!("  synced {f}");
                }
            }
        }
        Err(e) => {
            error!("{e}");
            return 1;
        }
    }
}

